"use client";

import { getProject, types, type ISheet } from "@theatre/core";
import state from "@/data/theatre/multiverse.json";
import pose from "@/data/theatre/multiverse-pose.json";

/*
 * The cinematic, as a Theatre.js project of its own ("CHRONOS · Multiverse").
 * Theatre owns the camera and the artistic intensities; it never runs the
 * simulation. During the cinematic the simulation's clock IS the sequence
 * position, so scrubbing in Studio replays exactly the same network
 * (see lib/multiverse/simulation.ts). The state is generated by
 * scripts/theatre-multiverse.mjs and can be refined in Studio (`?studio=1`).
 *
 * Ownership: camera position, target and fov belong to Theatre while the
 * cinematic plays, to the orbit controls afterwards. The world intensities
 * always come from here; the reader's sliders multiply them.
 */

export const CINEMATIC_RANGE = [0, 24] as const;
export type CinematicValues = typeof pose;
export const finalPose: CinematicValues = pose;

interface MultiverseTheatre {
  sheet: ISheet;
  /** Mutated by Theatre; read it in the render loop, never copy it into React state. */
  values: CinematicValues;
  ready: Promise<void>;
  /** Subscribes to the title's opacity (the one DOM property Theatre owns). */
  onTitle: (cb: (opacity: number) => void) => () => void;
  /** Called after any value changes (Theatre reports them asynchronously, once per frame at most). */
  onChange: (cb: () => void) => () => void;
}

let theatre: MultiverseTheatre | null = null;

export function getMultiverseTheatre(): MultiverseTheatre {
  if (theatre) return theatre;
  const project = getProject("CHRONOS · Multiverse", { state });
  const sheet = project.sheet("Cinematic");
  const values: CinematicValues = structuredClone(pose);
  const num = (value: number, range: [number, number]) => types.number(value, { range });

  const camera = sheet.object("camera", {
    x: num(pose.camera.x, [-200, 200]),
    y: num(pose.camera.y, [-200, 200]),
    z: num(pose.camera.z, [-200, 200]),
    fov: num(pose.camera.fov, [15, 90]),
  });
  const target = sheet.object("target", {
    x: num(pose.target.x, [-100, 100]),
    y: num(pose.target.y, [-100, 100]),
    z: num(pose.target.z, [-100, 100]),
  });
  const world = sheet.object("world", {
    exposure: num(pose.world.exposure, [0, 3]),
    filamentEnergy: num(pose.world.filamentEnergy, [0, 3]),
    particleSpeed: num(pose.world.particleSpeed, [0, 4]),
    bloomStrength: num(pose.world.bloomStrength, [0, 3]),
    instability: num(pose.world.instability, [0, 1]),
    branchDensity: num(pose.world.branchDensity, [0, 1]),
    fabric: num(pose.world.fabric, [0, 2]),
    title: num(pose.world.title, [0, 1]),
  });
  const titleListeners = new Set<(o: number) => void>();
  const changeListeners = new Set<() => void>();
  const changed = () => changeListeners.forEach((cb) => cb());
  camera.onValuesChange((v) => {
    Object.assign(values.camera, v);
    changed();
  });
  target.onValuesChange((v) => {
    Object.assign(values.target, v);
    changed();
  });
  world.onValuesChange((v) => {
    Object.assign(values.world, v);
    titleListeners.forEach((cb) => cb(v.title));
    changed();
  });

  theatre = {
    sheet,
    values,
    ready: project.ready.then(() => undefined),
    onTitle: (cb) => {
      titleListeners.add(cb);
      cb(values.world.title);
      return () => titleListeners.delete(cb);
    },
    onChange: (cb) => {
      changeListeners.add(cb);
      return () => changeListeners.delete(cb);
    },
  };
  return theatre;
}
